payload = '111111011111100'
def stuff(bits):
    out = []
    run = 0
    for b in bits:
        out.append(b)
        if b == '1':
            run += 1
            if run == 5:
                out.append('0')
                run = 0
        else:
            run = 0
    return ''.join(out)
stuffed = stuff(payload)
print(len(payload))
print(len(stuffed) - len(payload))
print(len(stuffed))
assert stuffed == '11111010111110100'
